import XCTest

final class BskyUnfollowTests: XCTestCase {
    let dir = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-tmp-noygjhli/uitest"

    func testTaps() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        sleep(2)
        let text = try String(contentsOfFile: dir + "/taps.txt", encoding: .utf8)
        let tag = try String(contentsOfFile: dir + "/tag.txt", encoding: .utf8).trimmingCharacters(in: .whitespacesAndNewlines)
        for (i, line) in text.split(separator: "\n").enumerated() {
            let parts = line.split(separator: " ")
            let x = Double(parts[0])!
            let y = Double(parts[1])!
            app.coordinate(withNormalizedOffset: CGVector(dx: x, dy: y)).tap()
            sleep(2)
            let png = try XCUIScreen.main.screenshot().pngRepresentation
            try png.write(to: URL(fileURLWithPath: "\(dir)/\(tag)_\(i).png"))
            print("TAPPED \(i) \(x) \(y)")
        }
        print("DONE")
    }
}

